//! Generator of `spec/vectors/pairing-v1/*.json` (`spec/pairing-v1.md` §14.1).
//!
//! The published vectors are FROZEN. This tool never overwrites a file: an existing file must be
//! regenerated byte for byte (otherwise it stops with an error), a missing file is created, and
//! `SHA256SUMS` may only gain lines. It writes only into the directory it is given.
//!
//! Every value is computed with `tests/common/pairing_reference.rs` (primitives and the text of the
//! specification only), then checked against the pairing machines of `tomi-core`
//! (`pairing::kat`), against the draft of CPace for `cpace-draft21.json`, and every failure case
//! is replayed through the machines before it is written.
//!
//! Usage: `cargo run -p tomi-core --example gen_pairing_vectors -- spec/vectors/pairing-v1`

#[path = "../tests/common/pairing_driver.rs"]
mod driver;
#[path = "../tests/common/pairing_reference.rs"]
mod reference;

use std::error::Error;
use std::fs;
use std::path::{Path, PathBuf};

use curve25519_dalek::ristretto::CompressedRistretto;
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use tomi_core::pairing::{self, kat, PairingCode};
use tomi_core::TrustStore;

use driver::{run_case, run_mitm, run_nominal, Attacker, Fixture, Frames};
use reference as r;
use reference::{h, unhex};

type R<T> = Result<T, Box<dyn Error>>;

const FROZEN_NOTE: &str =
    "FROZEN as of publication — never modify this file (spec/vectors/pairing-v1/README.md).";

fn check(cond: bool, what: &str) -> R<()> {
    if cond {
        Ok(())
    } else {
        Err(format!("self-check failed: {what}").into())
    }
}

fn check_eq(a: &str, b: &str, what: &str) -> R<()> {
    if a == b {
        Ok(())
    } else {
        Err(format!("self-check failed: {what}\n  computed: {a}\n  expected: {b}").into())
    }
}

fn sha(b: &[u8]) -> String {
    hex::encode(Sha256::digest(b))
}

/// Creates the file, or checks that the existing frozen file has exactly these bytes.
fn write_frozen(path: &Path, bytes: &[u8]) -> R<()> {
    if path.exists() {
        let existing = fs::read(path)?;
        if existing != bytes {
            return Err(format!(
                "{} differs from the regenerated vector: vectors are frozen",
                path.display()
            )
            .into());
        }
        println!("unchanged {}", path.display());
        return Ok(());
    }
    fs::write(path, bytes)?;
    println!("wrote {}", path.display());
    Ok(())
}

fn write(dir: &Path, name: &str, v: &Value) -> R<()> {
    let mut s = serde_json::to_string_pretty(v)?;
    s.push('\n');
    write_frozen(&dir.join(name), s.as_bytes())
}

fn main() -> R<()> {
    let dir: PathBuf = std::env::args()
        .nth(1)
        .ok_or("usage: gen_pairing_vectors <output dir>")?
        .into();
    if dir.ends_with("v1") {
        return Err(
            "refusing to write into a v1 directory: those vectors are frozen elsewhere".into(),
        );
    }
    fs::create_dir_all(&dir)?;

    write(&dir, "cpace-draft21.json", &cpace_draft21()?)?;
    write(&dir, "wordlist.json", &wordlist()?)?;
    write(&dir, "pairing.json", &pairing_vectors()?)?;

    // ------------------------------------------------------------ checksums
    let mut names: Vec<String> = fs::read_dir(&dir)?
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .filter(|n| n.ends_with(".json"))
        .collect();
    names.sort();
    let mut sums = String::new();
    for n in &names {
        sums.push_str(&format!("{}  {}\n", sha(&fs::read(dir.join(n))?), n));
    }
    let sums_path = dir.join("SHA256SUMS");
    if sums_path.exists() {
        // Only additions are allowed: every published line must still be there.
        let existing = fs::read_to_string(&sums_path)?;
        for line in existing.lines().filter(|l| !l.trim().is_empty()) {
            if !sums.lines().any(|l| l == line) {
                return Err(format!("SHA256SUMS would lose or change `{line}`").into());
            }
        }
        if existing == sums {
            println!("unchanged SHA256SUMS");
        } else {
            fs::write(&sums_path, &sums)?;
            println!("added lines to SHA256SUMS");
        }
    } else {
        fs::write(&sums_path, &sums)?;
        println!("wrote SHA256SUMS");
    }
    Ok(())
}

// ===========================================================================
// cpace-draft21.json
// ===========================================================================

// draft-irtf-cfrg-cpace-21, appendix B.3 (ristretto255, SHA-512), lowercase hexadecimal.
const D_CI: &str = "0b415f696e69746961746f720b425f726573706f6e646572";
const D_SID: &str = "7e4b4791d6a8ef019b936c79fb7f2c57";
const D_HASH: &str = "da6d3ddc8802fca9058755ffd3ebde08a9c2c74945901a258482a288b6663af06bf645c93cd1c51512307199c80e84908916d983b34af77205f90851a657ee27";
const D_G: &str = "222b6b195fe84b1652badb6f6a3ae3d24341e7306967f0b8115b40d5698c7e56";
const D_YA: &str = "da3d23700a9e5699258aef94dc060dfda5ebb61f02a5ea77fad53f4ff0976d08";
const D_YA_PUB: &str = "d6bac480f2c386c394efc7c47adb9925dcd2630b64f240c50f8d0eec482b9157";
const D_YB: &str = "d2316b454718c35362d83d69df6320f38578ed5984651435e2949762d900b80d";
const D_YB_PUB: &str = "3ea7e0b19560d7c0b0f5734f63b955286dfa8232b5ebe63324e2d9e7433f7258";
const D_K: &str = "80b69a8a76457ab6a4d7f887a4bf6b55a2f80ac19c333f917a05fc9887c8b40f";
const D_TRANSCRIPT: &str = "20d6bac480f2c386c394efc7c47adb9925dcd2630b64f240c50f8d0eec482b915703414461203ea7e0b19560d7c0b0f5734f63b955286dfa8232b5ebe63324e2d9e7433f725803414462";
const D_ISK_INPUT: &str = "15435061636552697374726574746f3235355f49534b107e4b4791d6a8ef019b936c79fb7f2c572080b69a8a76457ab6a4d7f887a4bf6b55a2f80ac19c333f917a05fc9887c8b40f20d6bac480f2c386c394efc7c47adb9925dcd2630b64f240c50f8d0eec482b915703414461203ea7e0b19560d7c0b0f5734f63b955286dfa8232b5ebe63324e2d9e7433f725803414462";
const D_ISK: &str = "b69effbf61b51d56401c0f65601abe428de8206feaaf0e32198896dcae7b35cd2b38950a39dfd5d4a79164614c2984f7daa460b588c1e80c3fa2068af7900447";
const D_S: &str = "7cd0e075fa7955ba52c02759a6c90dbbfc10e6d40aea8d283e407d88cf538a05";
const D_X: &str = "2c3c6b8c4f3800e7aef6864025b4ed79bd599117e427c41bd47d93d654b4a51c";
const D_X_RESULT: &str = "7c13645fe790a468f62c39beb7388e541d8405d1ade69d1778c5fe3e7f6b600e";
const D_Y_I1: &str = "2b3c6b8c4f3800e7aef6864025b4ed79bd599117e427c41bd47d93d654b4a51c";

fn cpace_draft21() -> R<Value> {
    let prs = b"Password".as_slice();
    let ci = unhex(D_CI);
    let sid = unhex(D_SID);
    let (ya, yb) = (r::arr::<32>(&unhex(D_YA)), r::arr::<32>(&unhex(D_YB)));

    // The draft's generator string: DSI, PRS, 100 zero bytes (length 0x64), CI, sid.
    let mut expected_gen_str = String::new();
    expected_gen_str.push_str("11435061636552697374726574746f3235350850617373776f7264");
    expected_gen_str.push_str("64");
    expected_gen_str.push_str(&"00".repeat(100));
    expected_gen_str.push_str("180b415f696e69746961746f720b425f726573706f6e646572");
    expected_gen_str.push_str("107e4b4791d6a8ef019b936c79fb7f2c57");

    // Reference implementation (primitives only).
    let gen_str = r::generator_string(prs, &ci, &sid);
    check_eq(&h(&gen_str), &expected_gen_str, "generator_string")?;
    check(gen_str.len() == 170, "generator_string length")?;
    check_eq(&h(&r::sha512(&[&gen_str])), D_HASH, "generator hash")?;
    let g = r::generator(&gen_str);
    check_eq(&h(&g.compress().to_bytes()), D_G, "generator g")?;
    let (ya_pub, yb_pub) = (r::share(&ya, &g), r::share(&yb, &g));
    check_eq(&h(&ya_pub), D_YA_PUB, "Ya")?;
    check_eq(&h(&yb_pub), D_YB_PUB, "Yb")?;
    let k_a = r::scalar_mult_vfy(&ya, &yb_pub);
    let k_b = r::scalar_mult_vfy(&yb, &ya_pub);
    check_eq(&h(&k_a), D_K, "K (initiator)")?;
    check_eq(&h(&k_b), D_K, "K (responder)")?;
    let transcript = {
        let mut t = r::lv_cat(&[&ya_pub, b"ADa"]);
        t.extend(r::lv_cat(&[&yb_pub, b"ADb"]));
        t
    };
    check_eq(&h(&transcript), D_TRANSCRIPT, "transcript_ir")?;
    let mut isk_input = r::lv_cat(&[r::DSI_ISK, &sid, &k_a]);
    isk_input.extend(&transcript);
    check_eq(
        &h(&isk_input),
        D_ISK_INPUT,
        "lv_cat(DSI_ISK, sid, K) || transcript",
    )?;
    let isk = r::isk(&sid, &k_a, &ya_pub, b"ADa", &yb_pub, b"ADb");
    check_eq(&h(&isk), D_ISK, "ISK (initiator-responder)")?;

    // The pairing module (known-answer hook) gives the same bytes.
    let trace = kat::cpace_trace(prs, &ci, &sid, b"ADa", b"ADb", &ya, &yb)?;
    check_eq(
        &h(&trace.generator_string),
        &expected_gen_str,
        "module: generator_string",
    )?;
    check_eq(&h(&trace.generator_hash), D_HASH, "module: hash")?;
    check_eq(&h(&trace.generator), D_G, "module: g")?;
    check_eq(&h(&trace.ya_public), D_YA_PUB, "module: Ya")?;
    check_eq(&h(&trace.yb_public), D_YB_PUB, "module: Yb")?;
    check_eq(&h(&trace.k_initiator), D_K, "module: K (initiator)")?;
    check_eq(&h(&trace.k_responder), D_K, "module: K (responder)")?;
    check_eq(&h(&trace.isk_initiator), D_ISK, "module: ISK (initiator)")?;
    check_eq(&h(&trace.isk_responder), D_ISK, "module: ISK (responder)")?;

    // scalar_mult_vfy: a valid input, and the two invalid inputs of B.3.11.
    let s = r::arr::<32>(&unhex(D_S));
    let x = r::arr::<32>(&unhex(D_X));
    check_eq(
        &h(&r::scalar_mult_vfy(&s, &x)),
        D_X_RESULT,
        "scalar_mult_vfy valid",
    )?;
    check_eq(
        &h(&kat::scalar_mult_vfy(&s, &x)),
        D_X_RESULT,
        "module: scalar_mult_vfy valid",
    )?;
    let y_i1 = r::arr::<32>(&unhex(D_Y_I1));
    let identity = [0u8; 32];
    check(
        CompressedRistretto(y_i1).decompress().is_none(),
        "Y_i1 does not decode",
    )?;
    for bad in [y_i1, identity] {
        check(
            r::scalar_mult_vfy(&s, &bad) == identity,
            "invalid input gives I",
        )?;
        check(
            kat::scalar_mult_vfy(&s, &bad) == identity,
            "module: invalid input gives I",
        )?;
    }

    // prepend_len (A.1.2) and lv_cat (A.1.4).
    let range = |n: u8| (0..n).collect::<Vec<u8>>();
    let prepend_cases: Vec<(&str, Vec<u8>, String)> = vec![
        ("b\"\"", Vec::new(), "00".into()),
        ("b\"1234\"", b"1234".to_vec(), "0431323334".into()),
        (
            "bytes(range(127))",
            range(127),
            format!("7f{}", h(&range(127))),
        ),
        (
            "bytes(range(128))",
            range(128),
            format!("8001{}", h(&range(128))),
        ),
    ];
    let mut prepend_values = Vec::new();
    for (name, data, want) in &prepend_cases {
        check_eq(&h(&r::prepend_len(data)), want, name)?;
        check_eq(&h(&kat::prepend_len(data)), want, name)?;
        prepend_values.push(json!({"data_rule": name, "data": h(data), "prepend_len": want}));
    }
    let lv = r::lv_cat(&[b"1234", b"5", b"", b"678"]);
    check_eq(&h(&lv), "043132333401350003363738", "lv_cat")?;
    check_eq(
        &h(&kat::lv_cat(&[b"1234", b"5", b"", b"678"])),
        "043132333401350003363738",
        "module: lv_cat",
    )?;

    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "CPace vectors of draft-irtf-cfrg-cpace-21 (appendix B.3, ristretto255 and SHA-512, initiator-responder mode), reproduced byte for byte (pairing-v1.md §3.3, §14.1). Invalid inputs of B.3.11: scalar_mult_vfy yields the neutral element I and the protocol aborts. prepend_len / lv_cat vectors of appendix A.1.",
        "source": "https://www.ietf.org/archive/id/draft-irtf-cfrg-cpace-21.txt",
        "suite": {
            "name": "CPACE-RISTR255-SHA512",
            "H": "SHA-512",
            "s_in_bytes": 128,
            "DSI_ascii": "CPaceRistretto255",
            "DSI": h(r::DSI),
            "DSI_ISK_ascii": "CPaceRistretto255_ISK",
            "DSI_ISK": h(r::DSI_ISK),
            "mode": "initiator-responder",
            "sample_scalar": "32 octets, b[31] &= 0x0f, entier little-endian (< 2^252)",
        },
        "calculate_generator": {
            "PRS_ascii": "Password",
            "PRS": h(prs),
            "zpad_len": 100,
            "CI": D_CI,
            "sid": D_SID,
            "generator_string": h(&gen_str),
            "generator_string_len": gen_str.len(),
            "hash": h(&r::sha512(&[&gen_str])),
            "g": D_G,
        },
        "message_a": {"ADa_ascii": "ADa", "ADa": h(b"ADa"), "ya": D_YA, "Ya": D_YA_PUB},
        "message_b": {"ADb_ascii": "ADb", "ADb": h(b"ADb"), "yb": D_YB, "Yb": D_YB_PUB},
        "shared": {"K_initiator": h(&k_a), "K_responder": h(&k_b)},
        "isk_initiator_responder": {
            "transcript_ir": h(&transcript),
            "lv_cat_dsi_sid_k_then_transcript": h(&isk_input),
            "ISK": h(&isk),
        },
        "scalar_mult_vfy": {
            "valid": {"s": D_S, "X": D_X, "result": D_X_RESULT},
            "invalid": [
                {"name": "Y_i1 (does not decode)", "s": D_S, "Y": D_Y_I1,
                 "result": h(&identity), "protocol": "abort"},
                {"name": "Y_i2 = G.I (neutral element)", "s": D_S, "Y": h(&identity),
                 "result": h(&identity), "protocol": "abort"},
            ],
        },
        "prepend_len": prepend_values,
        "lv_cat": [{"args": ["31323334", "35", "", "363738"], "result": h(&lv)}],
    }))
}

// ===========================================================================
// wordlist.json
// ===========================================================================

const LIST_FILE_SHA256: &str = "ebc3959ab7801a1df6bac4fa7d970652f1df76b683cd2f4003c941c63d517e59";
const LIST_FOLDED_SHA256: &str = "cf8db448ad5ca0b68c3c8f88b51458f20362a5939fef236fac64a303f1485e87";

fn wordlist() -> R<Value> {
    // The embedded list, as public API sees it.
    let words: Vec<&str> = (0..pairing::WORD_COUNT as u16)
        .map(|i| pairing::word(i).ok_or("word"))
        .collect::<Result<_, _>>()?;
    let mut text = words.join("\n");
    text.push('\n');
    check(text.len() == 16_001, "folded list length")?;
    check_eq(
        &sha(text.as_bytes()),
        LIST_FOLDED_SHA256,
        "folded list sha256",
    )?;
    check(
        words
            .iter()
            .all(|w| (5..=8).contains(&w.len()) && w.bytes().all(|b| b.is_ascii_lowercase())),
        "word shape",
    )?;
    let mut prefixes: Vec<&str> = words.iter().map(|w| &w[..4]).collect();
    prefixes.sort();
    prefixes.dedup();
    check(prefixes.len() == 2048, "distinct 4-letter prefixes")?;

    // Examples of Annex B: (rank, folded word, original spelling).
    let examples: [(u16, &str, &str); 7] = [
        (0, "abaisser", "abaisser"),
        (465, "crayon", "crayon"),
        (616, "ecole", "\u{e9}cole"),
        (642, "eleve", "\u{e9}l\u{e8}ve"),
        (1633, "renard", "renard"),
        (1891, "tomate", "tomate"),
        (2047, "zoologie", "zoologie"),
    ];
    let mut ranks = Vec::new();
    for (rank, word, original) in examples {
        check(pairing::word(rank) == Some(word), "rank to word")?;
        check(pairing::rank_of(word) == Some(rank), "word to rank")?;
        ranks.push(json!({"rank": rank, "word": word, "original_nfc": original,
                          "original_nfc_utf8": h(original.as_bytes())}));
    }

    // Reading a typed code (§4.4). The inputs are given as UTF-8 hexadecimal: the exact
    // normalisation form of each input is part of the vector.
    let accepted: [(&str, &str, [u16; 2]); 15] = [
        ("4821-crayon-renard", "4821", [465, 1633]),
        ("4821 Crayon RENARD", "4821", [465, 1633]),
        ("4821-crayo-rena", "4821", [465, 1633]),
        ("4821_crayon.renard", "4821", [465, 1633]),
        ("4821-cr\u{e2}yon-renard", "4821", [465, 1633]),
        ("4821-cra\u{302}yon-renard", "4821", [465, 1633]),
        ("4821-\u{e9}cole-\u{e9}l\u{e8}ve", "4821", [616, 642]),
        ("4821-e\u{301}cole-e\u{301}le\u{300}ve", "4821", [616, 642]),
        ("4821-ecole-eleve", "4821", [616, 642]),
        ("  4821-crayon-renard\n", "4821", [465, 1633]),
        ("1-abai-zool", "1", [0, 2047]),
        ("9999-abaisser-zoologie", "9999", [0, 2047]),
        ("12-crayon-crayon", "12", [465, 465]),
        ("\u{ff14}\u{ff18}\u{ff12}\u{ff11}-\u{ff43}\u{ff52}\u{ff41}\u{ff59}\u{ff4f}\u{ff4e}-\u{ff52}\u{ff45}\u{ff4e}\u{ff41}\u{ff52}\u{ff44}", "4821", [465, 1633]),
        ("4821\u{a0}crayon\u{2014}renard", "4821", [465, 1633]),
    ];
    let refused: [(&str, &str); 14] = [
        ("0-crayon-renard", "channel number with a zero, value 0"),
        ("04821-crayon-renard", "channel number with a leading zero"),
        ("0482-crayon-renard", "channel number with a leading zero"),
        ("10000-crayon-renard", "channel number above 9999"),
        ("4821-cra-renard", "word prefix below 4 letters"),
        ("4821-crayon", "two tokens"),
        ("4821-crayon-renard-tomate", "four tokens"),
        ("4821-xylophone-renard", "unknown word"),
        ("4821-crayonn-renard", "unknown word, not a prefix"),
        ("4821-lune-renard", "unknown word (lune is not in the list)"),
        ("4821-cr4yon-renard", "a digit inside a word"),
        (
            "\u{664}\u{668}\u{662}\u{661}-crayon-renard",
            "Arabic-Indic digits are not ASCII digits",
        ),
        ("\u{967}-crayon-renard", "Devanagari digit"),
        ("", "empty"),
    ];
    let mut reading = Vec::new();
    for (input, channel, want) in accepted {
        let c = PairingCode::parse(input)?;
        check(c.channel_id() == channel && c.ranks() == want, input)?;
        reading.push(json!({
            "input": input, "input_utf8": h(input.as_bytes()),
            "accepted": true, "channel_id": channel, "ranks": want,
        }));
    }
    for (input, why) in refused {
        check(PairingCode::parse(input).is_err(), input)?;
        reading.push(json!({
            "input": input, "input_utf8": h(input.as_bytes()),
            "accepted": false, "why": why,
        }));
    }

    // Links (§4.3, §4.4 rule 1) against the relay authority compiled into the app.
    let authority = "relay.example.org";
    let link_ok = [
        "https://relay.example.org/l/pair#4821-crayon-renard",
        "tomi-share://pair#4821-crayon-renard",
        "https://relay.example.org/l/pair#4821-crayo-rena",
    ];
    let link_bad: [(&str, &str); 7] = [
        (
            "https://evil.example/l/pair#4821-crayon-renard",
            "another host",
        ),
        (
            "https://relay.example.org.evil.example/l/pair#4821-crayon-renard",
            "host suffix",
        ),
        ("http://relay.example.org/l/pair#4821-crayon-renard", "http"),
        (
            "https://relay.example.org/l/other#4821-crayon-renard",
            "another path",
        ),
        (
            "https://relay.example.org/l/pair?code=4821-crayon-renard",
            "code in the query string",
        ),
        ("https://relay.example.org/l/pair", "no fragment"),
        (
            "tomi-share://other#4821-crayon-renard",
            "another host in the tomi-share scheme",
        ),
    ];
    let mut links = Vec::new();
    for input in link_ok {
        let c = PairingCode::from_link(input, authority)?;
        check(c.channel_id() == "4821" && c.ranks() == [465, 1633], input)?;
        links.push(
            json!({"input": input, "accepted": true, "channel_id": "4821", "ranks": [465, 1633]}),
        );
    }
    for (input, why) in link_bad {
        check(PairingCode::from_link(input, authority).is_err(), input)?;
        links.push(json!({"input": input, "accepted": false, "why": why}));
    }
    // Showing a code: the link of the QR code and the PRS.
    let shown = PairingCode::parse("4821-crayon-renard")?;
    check(
        shown.link(authority) == "https://relay.example.org/l/pair#4821-crayon-renard",
        "link",
    )?;
    check(
        shown.deep_link() == "tomi-share://pair#4821-crayon-renard",
        "deep link",
    )?;
    check(h(shown.prs().as_slice()) == "01d10661", "prs")?;

    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "Word list of the pairing code (appendix B), ranks, PRS and reading of a code or a link (§4.3, §4.4, §14.1). Only the unambiguous behaviors of the spec are frozen here.",
        "source": {
            "name": "BIP-39, French list (bip-0039/french.txt, bitcoin/bips repository, MIT license)",
            "file_bytes": 16777,
            "file_sha256": LIST_FILE_SHA256,
            "note": "The published file is UTF-8 with decomposed accents (NFD); appendix B says NFC. The fingerprint is that of the published file.",
        },
        "folded": {
            "rule": "NFKD, combining marks (Mn) removed, lowercase",
            "word_count": 2048,
            "bytes": 16001,
            "sha256": LIST_FOLDED_SHA256,
            "word_length": [5, 8],
            "distinct_prefix_length": 4,
            "order": "in the order of the original list, also sorted in byte order",
        },
        "ranks": ranks,
        "prs": [{"ranks": [465, 1633], "prs": "01d10661"}],
        "reading": reading,
        "links": {"relay_authority": authority, "cases": links},
        "shown": {
            "code": "4821-crayon-renard",
            "link": "https://relay.example.org/l/pair#4821-crayon-renard",
            "deep_link": "tomi-share://pair#4821-crayon-renard",
        },
    }))
}

// ===========================================================================
// pairing.json
// ===========================================================================

fn device_value(d: &r::Device) -> Value {
    json!({
        "name": d.name,
        "ed25519_public": h(&d.ed_pk),
        "x25519_public": h(&d.x_pk),
        "device_id": d.device_id(),
    })
}

fn nominal_ref(k: usize) -> Value {
    json!({"nominal": k})
}

fn other_ref(k: usize) -> Value {
    json!({"other": k})
}

fn hex_ref(b: &[u8]) -> Value {
    json!({"hex": h(b)})
}

fn recv(frame: Value, expect: &str) -> Value {
    json!({"do": "receive", "frame": frame, "expect": expect})
}

fn recv_p(frame: Value, produces: Value) -> Value {
    json!({"do": "receive", "frame": frame, "expect": "ok", "produces": produces})
}

fn case(
    id: &str,
    pxx: &str,
    description: &str,
    receiver: &str,
    setup: Value,
    steps: Vec<Value>,
    final_error: Option<&str>,
) -> Value {
    json!({
        "id": id, "pxx": pxx, "description": description,
        "receiver": receiver, "setup": setup, "steps": steps,
        "final_error": final_error,
    })
}

/// What the receiver has done when it is about to read frame `k` of the nominal sequence.
/// Frames: 0 commit (A to N), 1 share, 2 reveal (A to N), 3 hello, 4 confirm, 5 provision (A to N), 6 ack.
fn is_for_joiner(k: usize) -> bool {
    matches!(k, 0 | 2 | 5)
}

fn prefix_steps(k: usize) -> Vec<Value> {
    let mut steps = Vec::new();
    match k {
        0 | 1 => {}
        2 => steps.push(recv_p(nominal_ref(0), nominal_ref(1))),
        3 => steps.push(recv_p(nominal_ref(1), nominal_ref(2))),
        4 => {
            steps.push(recv_p(nominal_ref(1), nominal_ref(2)));
            steps.push(recv(nominal_ref(3), "ok"));
            steps.push(json!({"do": "user_confirm"}));
        }
        5 => {
            steps.push(recv_p(nominal_ref(0), nominal_ref(1)));
            steps.push(recv_p(nominal_ref(2), nominal_ref(3)));
            steps
                .push(json!({"do": "joiner_confirm", "history": true, "produces": nominal_ref(4)}));
        }
        6 => {
            steps.push(recv_p(nominal_ref(1), nominal_ref(2)));
            steps.push(recv(nominal_ref(3), "ok"));
            steps.push(json!({"do": "user_confirm"}));
            steps.push(recv(nominal_ref(4), "ok"));
            steps.push(json!({"do": "provision", "produces": nominal_ref(5)}));
        }
        _ => unreachable!("seven frames"),
    }
    steps
}

fn receiver_of(k: usize) -> &'static str {
    if is_for_joiner(k) {
        "joiner"
    } else {
        "inviter"
    }
}

/// One altered frame delivered at its place in the sequence; the first error is the expected one.
fn altered_case(
    id: &str,
    pxx: &str,
    description: &str,
    k: usize,
    frame: &[u8],
    expect: &str,
) -> Value {
    let mut steps = prefix_steps(k);
    steps.push(recv(hex_ref(frame), expect));
    case(
        id,
        pxx,
        description,
        receiver_of(k),
        json!({}),
        steps,
        Some(expect),
    )
}

/// A clear frame (`commit`, `share`) altered in its payload is accepted when it is read (nothing
/// authenticates it yet): the key agreement fails on the next frame, which is the genuine one.
fn altered_clear_case(
    id: &str,
    description: &str,
    k: usize,
    frame: &[u8],
    accepted_now: bool,
) -> Value {
    let mut steps = prefix_steps(k);
    let next = if k == 0 { 2 } else { 3 };
    if accepted_now {
        steps.push(recv(hex_ref(frame), "ok"));
        steps.push(recv(nominal_ref(next), "pairing_failed"));
    } else {
        steps.push(recv(hex_ref(frame), "pairing_failed"));
    }
    case(
        id,
        "P12",
        description,
        receiver_of(k),
        json!({}),
        steps,
        Some("pairing_failed"),
    )
}

fn pairing_vectors() -> R<Value> {
    let inputs = r::nominal_inputs();
    let s = r::session(&inputs);
    let fx = Fixture::new(&inputs);

    // The module reproduces every byte of the reference session.
    let run = run_nominal(&fx);
    for (k, (got, want)) in run.frames.iter().zip(&s.frames).enumerate() {
        check_eq(
            &h(got),
            &h(want),
            &format!("module frame {k} ({})", r::FRAME_NAMES[k]),
        )?;
    }
    check(
        run.sas_inviter == format!("{:06}", s.sas),
        "module SAS of A",
    )?;
    check(run.sas_joiner == format!("{:06}", s.sas), "module SAS of N")?;

    // The trust stores, through the API of the core (their JSON is the core's own format).
    let a_pub = fx.keys_inviter.public();
    let b_keys = driver::device_keys(&inputs.joiner);
    let mut trust_n = TrustStore::new(&inputs.space_id, &b_keys.public(), inputs.key_epoch)?;
    trust_n.add_verified_peer(&a_pub)?;
    trust_n.accept_member_list(&tomi_core::MemberList::from_bytes(&s.member_list)?)?;
    let trust_n_json = trust_n.to_json()?;
    check(
        run.provision.trust.to_json()? == trust_n_json,
        "module: trust store of N",
    )?;
    check(run.provision.trust.members().len() == 3, "N knows A, B, C")?;
    let staged_json = run.outcome.staged_trust.to_json()?;
    check(
        run.provision.space_key.to_bytes() == inputs.space_key,
        "N holds the space key",
    )?;
    let transfer_id = r::uuid_string(&r::uuid_v4(&inputs.transfer_random));
    check(
        run.outcome.history.as_ref().map(|x| x.transfer_id.as_str()) == Some(transfer_id.as_str()),
        "history transfer id",
    )?;
    check(run.outcome.device_cert == s.cert, "module: DeviceCert(N)")?;

    // ---------------------------------------------------------------- frames
    let who = |k: usize| {
        if is_for_joiner(k) {
            ("A", "N")
        } else {
            ("N", "A")
        }
    };
    let mut frames = Vec::new();
    for k in 0..7 {
        let t = r::FRAME_TYPES[k];
        let (from, to) = who(k);
        let sealing = r::sealing(t);
        let (key_name, n) = match sealing {
            Some((true, n)) => (Value::from("K_I"), Value::from(n)),
            Some((false, n)) => (Value::from("K_J"), Value::from(n)),
            None => (Value::Null, Value::Null),
        };
        let mut v = json!({
            "index": k, "name": r::FRAME_NAMES[k], "type": t, "from": from, "to": to,
            "key": key_name, "nonce_counter": n,
            "size": s.frames[k].len(), "frame": h(&s.frames[k]),
        });
        if sealing.is_some() {
            v["aad"] = json!(h(&r::aad(t, &inputs.sid)));
            v["nonce"] = json!(h(&r::nonce(sealing.map_or(0, |x| x.1))));
            v["body"] = json!(h(&s.bodies[k]));
            let payload_start = if k == 2 { 2 + 32 } else { 2 };
            v["box"] = json!(h(&s.frames[k][payload_start..]));
        }
        frames.push(v);
    }

    // ---------------------------------------------------------------- the batch, decoded
    let name_of = |ed: &[u8; 32]| -> &'static str {
        [&inputs.inviter, &inputs.joiner, &inputs.other]
            .iter()
            .find(|d| &d.ed_pk == ed)
            .map_or("?", |d| d.name)
    };
    let mut members = [
        (inputs.inviter.ed_pk, inputs.inviter.x_pk),
        (inputs.other.ed_pk, inputs.other.x_pk),
        (inputs.joiner.ed_pk, inputs.joiner.x_pk),
    ];
    members.sort();
    let history = s.history.map(|(id, items, bytes)| {
        json!({"transfer_id": r::uuid_string(&id), "transfer_id_bytes": h(&id), "items": items, "bytes": bytes})
    });
    let provision = json!({
        "space_id": inputs.space_id,
        "space_id_bytes": h(&r::uuid16(&inputs.space_id)),
        "key_epoch": inputs.key_epoch,
        "sealed": {"hex": h(&s.sealed), "len": s.sealed.len(), "for": "B"},
        "device_cert": {
            "wire": h(&s.cert), "len": s.cert.len(), "subject": "B", "issuer": "A",
            "issued_at_ms": inputs.now_ms,
        },
        "member_list": {
            "wire": h(&s.member_list), "len": s.member_list.len(), "issuer": "A",
            "key_epoch": inputs.key_epoch, "issued_at_ms": inputs.now_ms,
            "members_order": members.iter().map(|(ed, _)| name_of(ed)).collect::<Vec<_>>(),
        },
        "history": history,
        "body": h(&s.provision_body),
    });

    // ---------------------------------------------------------------- another session (P14)
    let mut other_inputs = inputs.clone();
    other_inputs.sid = r::arr(&r::seq(0x80, 16));
    other_inputs.ya = r::arr(&unhex(
        "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f00",
    ));
    other_inputs.yb = r::arr(&unhex(
        "a1a2a3a4a5a6a7a8a9aaabacadaeafb0b1b2b3b4b5b6b7b8b9babbbcbdbebf00",
    ));
    let other = r::session(&other_inputs);
    check(other.frames != s.frames, "the other session differs")?;

    // ---------------------------------------------------------------- P11: man in the middle
    let attacker = Attacker {
        sid: r::arr(&r::seq(0xf0, 16)),
        ya: r::arr(&unhex(
            "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f00",
        )),
        yb: r::arr(&unhex(
            "a1a2a3a4a5a6a7a8a9aaabacadaeafb0b1b2b3b4b5b6b7b8b9babbbcbdbebf00",
        )),
    };
    let yb_runs = [
        inputs.yb,
        r::arr::<32>(&unhex(
            "0f0e0d0c0b0a09080706050403020100ffeeddccbbaa99887766554433221100",
        )),
    ];
    let mut mitm_runs = Vec::new();
    for yb_n in yb_runs {
        // Reference: the session between A and the attacker (the attacker is N there) and the
        // one between the attacker (inviter, committed first) and N.
        let mut with_a = inputs.clone();
        with_a.yb = attacker.yb;
        let sa = r::session(&with_a);
        let mut with_n = inputs.clone();
        with_n.sid = attacker.sid;
        with_n.ya = attacker.ya;
        with_n.yb = yb_n;
        let sn = r::session(&with_n);
        let commit_m = sn.frames[0].clone();
        let (sas_a, sas_n, commit_machines) = run_mitm(&fx, &attacker, yb_n);
        check(sas_a == format!("{:06}", sa.sas), "MITM: SAS of A")?;
        check(sas_n == format!("{:06}", sn.sas), "MITM: SAS of N")?;
        check(
            commit_machines == commit_m,
            "MITM: the commit of the attacker",
        )?;
        mitm_runs.push(json!({
            "yb_joiner": h(&yb_n),
            "sas_inviter": sas_a, "sas_joiner": sas_n,
            "attacker_commit_frame": h(&commit_m),
        }));
    }
    check(
        mitm_runs[0]["sas_inviter"] == mitm_runs[1]["sas_inviter"],
        "A's code does not depend on yb of N",
    )?;
    check(
        mitm_runs[0]["sas_joiner"] != mitm_runs[1]["sas_joiner"],
        "N's code depends on yb of N",
    )?;
    check(
        mitm_runs[0]["sas_inviter"] != mitm_runs[0]["sas_joiner"],
        "the two codes differ",
    )?;
    check(
        mitm_runs[0]["attacker_commit_frame"] == mitm_runs[1]["attacker_commit_frame"],
        "the commit was fixed before yb of N",
    )?;

    // ---------------------------------------------------------------- the failure cases
    let mut cases = Vec::new();
    cases.extend(p09_p10_cases(&inputs, &s)?);
    cases.extend(p12_cases(&inputs, &s)?);
    cases.extend(p13_cases());
    cases.extend(p14_cases());
    cases.extend(p15_cases(&inputs, &s));
    cases.extend(p16_cases(&inputs, &s));
    // Every case is replayed through the machines before it is written.
    let nominal_frames: Vec<Vec<u8>> = s.frames.clone();
    let other_frames: Vec<Vec<u8>> = other.frames.clone();
    let frames_ref = Frames {
        nominal: &nominal_frames,
        other: &other_frames,
    };
    for c in &cases {
        run_case(&fx, c, &frames_ref)?;
    }

    Ok(json!({
        "frozen": FROZEN_NOTE,
        "description": "A complete, deterministic pairing session (pairing-v1.md §14.1): inputs, intermediate values, the 7 frames, the decoded batch, N's TrustStore, a second session (replay), a relay that knows the code (P11) and the failure cases P9 to P17. Devices A, B, C are those of spec/vectors/v1/device.json (A invites, B is the new device, C is already a member).",
        "inputs": {
            "relay_authority": inputs.relay_authority,
            "channel_id": inputs.channel_id,
            "words": ["crayon", "renard"],
            "ranks": inputs.ranks,
            "sid": h(&inputs.sid),
            "ya": h(&inputs.ya),
            "yb": h(&inputs.yb),
            "devices_file": "spec/vectors/v1/device.json",
            "inviter": device_value(&inputs.inviter),
            "joiner": device_value(&inputs.joiner),
            "other_member": device_value(&inputs.other),
            "space_id": inputs.space_id,
            "key_epoch": inputs.key_epoch,
            "space_key": h(&inputs.space_key),
            "seal_ephemeral_secret": h(&inputs.seal_ephemeral),
            "seal_nonce": h(&inputs.seal_nonce),
            "now_ms": inputs.now_ms,
            "inviter_name": inputs.inviter_name,
            "inviter_platform": inputs.inviter_platform,
            "joiner_name": inputs.joiner_name,
            "joiner_platform": inputs.joiner_platform,
            "member_count": inputs.member_count,
            "history_offer": inputs.offer.map(|(items, bytes)| json!({"items": items, "bytes": bytes})),
            "joiner_wants_history": inputs.joiner_wants_history,
            "transfer_id_random": h(&inputs.transfer_random),
        },
        "outputs": {
            "prs": h(&s.prs),
            "ci": h(&s.ci),
            "ada": h(&s.ada),
            "adb": h(&s.adb),
            "generator_string": h(&s.gen_str),
            "generator_string_len": s.gen_str.len(),
            "generator_hash": h(&s.gen_hash),
            "g": h(&s.g),
            "Ya": h(&s.ya_pub),
            "Yb": h(&s.yb_pub),
            "commit": h(&s.commit),
            "K": h(&s.k),
            "ISK": h(&s.isk),
            "K_I": h(&s.keys.k_i),
            "K_J": h(&s.keys.k_j),
            "sas_s8": h(&s.s8),
            "sas": format!("{:06}", s.sas),
            "sas_grouped": format!("{:03} {:03}", s.sas / 1000, s.sas % 1000),
            "transfer_id": transfer_id,
        },
        "frames": frames,
        "provision": provision,
        "trust_store_joiner": trust_n_json,
        "trust_store_inviter_staged": staged_json,
        "other_session": {
            "sid": h(&other_inputs.sid), "ya": h(&other_inputs.ya), "yb": h(&other_inputs.yb),
            "frames": other.frames.iter().map(|f| h(f)).collect::<Vec<_>>(),
        },
        "mitm": {
            "description": "P11: a relay that knows the code holds two sessions. It plays N towards A and A towards N. Its commitment (commit) is sent before it sees N's share: the two verification codes come from two independent ISKs, N's changes with N's yb, A's does not, and the commitment does not change.",
            "attacker": {"sid": h(&attacker.sid), "ya": h(&attacker.ya), "yb_toward_inviter": h(&attacker.yb)},
            "runs": mitm_runs,
        },
        "failures": cases,
    }))
}

/// Builds the first N -> A frames needed to reach a state, from the reference session.
fn p09_p10_cases(i: &r::Inputs, s: &r::Session) -> R<Vec<Value>> {
    let mut cases = Vec::new();

    // P9: N types a neighbouring word. A answers the share of N with a reveal that N can not open.
    for wrong in [[466u16, 1633], [465, 1632], [0, 0]] {
        let prs = r::prs(wrong);
        let gen_str = r::generator_string(&prs, &s.ci, &i.sid);
        let g = r::generator(&gen_str);
        let yb_pub = r::share(&i.yb, &g);
        let k = r::scalar_mult_vfy(&i.ya, &yb_pub);
        let isk = r::isk(&i.sid, &k, &s.ya_pub, &s.ada, &yb_pub, &s.adb);
        let keys = r::Keys::from_isk(&isk);
        let reveal = r::reveal_frame(&keys, &i.sid, &s.ya_pub, &s.inviter_hello);
        let share = r::frame(0x02, &yb_pub);
        cases.push(case(
            &format!("p09-wrong-code-{}-{}", wrong[0], wrong[1]),
            "P9",
            "N types a different word: its share Yb is computed on a different generator, A answers it, N does not open the reveal. Failure pairing_failed; A will never receive a joiner_hello.",
            "joiner",
            json!({"joiner_ranks": wrong}),
            vec![
                recv_p(nominal_ref(0), hex_ref(&share)),
                recv(hex_ref(&reveal), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ));
    }

    // P9 other causes: all the same error. A reveal whose point does not decode, or is the
    // neutral element, with a commit that matches it.
    let invalid_point = unhex(D_Y_I1);
    let neutral = vec![0u8; 32];
    for (name, point) in [
        ("invalid-point", invalid_point),
        ("neutral-element", neutral),
    ] {
        let mut commit_payload = i.sid.to_vec();
        commit_payload.extend(r::commit(&i.sid, &point));
        let commit = r::frame(0x01, &commit_payload);
        let reveal = r::reveal_frame(&s.keys, &i.sid, &point, &s.inviter_hello);
        cases.push(case(
            &format!("p09-{name}"),
            "P9",
            "The revealed point Ya does not decode, or it is the neutral element (K = I): the commitment matches, the session aborts, with the same error as a wrong code.",
            "joiner",
            json!({}),
            vec![
                recv_p(hex_ref(&commit), json!({"nominal": 1})),
                recv(hex_ref(&reveal), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ));
    }

    // P10: the reveal carries another Ya than the committed one, with a valid box for that Ya.
    let other_ya = r::arr::<32>(&unhex(
        "1111111111111111111111111111111111111111111111111111111111111101",
    ));
    let g = r::generator(&s.gen_str);
    let other_pub = r::share(&other_ya, &g);
    let k = r::scalar_mult_vfy(&other_ya, &s.yb_pub);
    let isk = r::isk(&i.sid, &k, &other_pub, &s.ada, &s.yb_pub, &s.adb);
    let keys = r::Keys::from_isk(&isk);
    let betrayal = r::reveal_frame(&keys, &i.sid, &other_pub, &s.inviter_hello);
    cases.push(case(
        "p10-betrayed-commitment",
        "P10",
        "A committed to Ya (nominal commit) but reveals Ya' with a box valid for Ya'. Only the commitment stops it: pairing_failed.",
        "joiner",
        json!({}),
        vec![
            recv_p(nominal_ref(0), nominal_ref(1)),
            recv(hex_ref(&betrayal), "pairing_failed"),
        ],
        Some("pairing_failed"),
    ));
    // Control: the same reveal is accepted when the commit was made on Ya'.
    let mut commit_payload = i.sid.to_vec();
    commit_payload.extend(r::commit(&i.sid, &other_pub));
    let honest_commit = r::frame(0x01, &commit_payload);
    cases.push(case(
        "p10-control-commitment-matches",
        "P10",
        "Control: if the commitment is over Ya', the same reveal is accepted (the box and the key are valid): only the commitment tells the two cases apart.",
        "joiner",
        json!({}),
        vec![
            recv_p(hex_ref(&honest_commit), nominal_ref(1)),
            recv(hex_ref(&betrayal), "ok"),
        ],
        None,
    ));
    Ok(cases)
}

fn p12_cases(_i: &r::Inputs, s: &r::Session) -> R<Vec<Value>> {
    let mut cases = Vec::new();
    for k in 0..7 {
        let original = &s.frames[k];
        let len = original.len();
        let name = r::FRAME_NAMES[k];

        // A bit flipped in the header, at the start, middle and end of the payload, and in the tag.
        for offset in [0usize, 1, 2, len / 2, len - 1] {
            let mut altered = original.clone();
            altered[offset] ^= 0x01;
            let id = format!("p12-flip-{name}-byte-{offset}");
            let desc = format!("Frame {k} ({name}): bit 0 of byte {offset} is flipped.");
            if offset == 0 && k <= 1 {
                // The first frame each side reads: an unknown version means "update Tomi".
                cases.push(altered_case(
                    &id,
                    "P12",
                    &desc,
                    k,
                    &altered,
                    "pairing_unsupported",
                ));
            } else if k <= 1 && offset >= 2 {
                // Clear frames: nothing authenticates them yet when they are read.
                let accepted_now = if k == 0 {
                    true
                } else {
                    // `share`: A accepts it unless Yb no longer decodes.
                    CompressedRistretto(r::arr(&altered[2..]))
                        .decompress()
                        .is_some()
                };
                cases.push(altered_clear_case(&id, &desc, k, &altered, accepted_now));
            } else {
                cases.push(altered_case(
                    &id,
                    "P12",
                    &desc,
                    k,
                    &altered,
                    "pairing_failed",
                ));
            }
        }

        // An unknown type, a truncated frame, a frame too long.
        let mut v = original.clone();
        v[1] = 0x08;
        cases.push(altered_case(
            &format!("p12-type-0x08-{name}"),
            "P12",
            &format!("Frame {k} ({name}): type 0x08, reserved, hence pairing_failed."),
            k,
            &v,
            "pairing_failed",
        ));
        cases.push(altered_case(
            &format!("p12-one-byte-short-{name}"),
            "P12",
            &format!("Frame {k} ({name}) with its last byte removed."),
            k,
            &original[..len - 1],
            "pairing_failed",
        ));
        let mut v = original.clone();
        v.push(0);
        cases.push(altered_case(
            &format!("p12-one-byte-long-{name}"),
            "P12",
            &format!("Frame {k} ({name}) with one byte too many."),
            k,
            &v,
            "pairing_failed",
        ));
    }
    // Header only, empty, a single byte, more than 8192 bytes.
    cases.push(altered_case(
        "p12-header-only",
        "P12",
        "A frame reduced to its header (version, type commit).",
        0,
        &[1, 1],
        "pairing_failed",
    ));
    cases.push(altered_case(
        "p12-empty",
        "P12",
        "An empty frame.",
        0,
        &[],
        "pairing_failed",
    ));
    cases.push(altered_case(
        "p12-single-byte",
        "P12",
        "A single-byte frame.",
        0,
        &[1],
        "pairing_failed",
    ));
    // 8193 bytes: described, not written out (16 KB of zeros).
    let mut steps = prefix_steps(2);
    steps.push(recv(
        json!({"padded": {"prefix": "0103", "len": 8193}}),
        "pairing_failed",
    ));
    cases.push(case(
        "p12-over-8192-bytes",
        "P12",
        "A frame of 8193 bytes (limit 8192).",
        "joiner",
        json!({}),
        steps,
        Some("pairing_failed"),
    ));
    // Version 2 in the first frame read: unsupported; in a later one: a failure.
    let mut v2 = s.frames[0].clone();
    v2[0] = 2;
    cases.push(altered_case(
        "p12-version-2-first-frame-joiner",
        "P12",
        "PAIR_VERSION = 2 in the first frame read by N: pairing_unsupported.",
        0,
        &v2,
        "pairing_unsupported",
    ));
    let mut v2 = s.frames[1].clone();
    v2[0] = 2;
    cases.push(altered_case(
        "p12-version-2-first-frame-inviter",
        "P12",
        "PAIR_VERSION = 2 in the first frame read by A: pairing_unsupported.",
        1,
        &v2,
        "pairing_unsupported",
    ));
    let mut v2 = s.frames[2].clone();
    v2[0] = 2;
    cases.push(altered_case(
        "p12-version-2-later-frame",
        "P12",
        "PAIR_VERSION = 2 in a later frame: pairing_failed.",
        2,
        &v2,
        "pairing_failed",
    ));
    let mut unknown_type_first = s.frames[0].clone();
    unknown_type_first[0] = 2;
    unknown_type_first[1] = 0x42;
    cases.push(altered_case("p12-version-2-unknown-type", "P12", "Unknown version and unknown type in the first frame: the version wins, pairing_unsupported.", 0, &unknown_type_first, "pairing_unsupported"));
    Ok(cases)
}

fn p13_cases() -> Vec<Value> {
    let d = "P13";
    let none = json!({});
    let mut cases = vec![
        case(
            "p13-reveal-before-share",
            d,
            "reveal received by A before the share.",
            "inviter",
            none.clone(),
            vec![recv(nominal_ref(2), "pairing_failed")],
            Some("pairing_failed"),
        ),
        case(
            "p13-reveal-before-commit",
            d,
            "reveal received by N before the commit.",
            "joiner",
            none.clone(),
            vec![recv(nominal_ref(2), "pairing_failed")],
            Some("pairing_failed"),
        ),
        case(
            "p13-two-commits",
            d,
            "Two commits: the second arrives while N is waiting for the reveal.",
            "joiner",
            none.clone(),
            vec![
                recv_p(nominal_ref(0), nominal_ref(1)),
                recv(nominal_ref(0), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ),
        case(
            "p13-confirm-before-hello",
            d,
            "joiner_confirm received by A before joiner_hello.",
            "inviter",
            none.clone(),
            vec![
                recv_p(nominal_ref(1), nominal_ref(2)),
                recv(nominal_ref(4), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ),
        case(
            "p13-provision-before-confirm",
            d,
            "provision received by N before joiner_confirm (it is still comparing the codes).",
            "joiner",
            none.clone(),
            vec![
                recv_p(nominal_ref(0), nominal_ref(1)),
                recv_p(nominal_ref(2), nominal_ref(3)),
                recv(nominal_ref(5), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ),
        case(
            "p13-ack-before-provision",
            d,
            "joiner_ack received by A before provision is sent.",
            "inviter",
            none.clone(),
            vec![
                recv_p(nominal_ref(1), nominal_ref(2)),
                recv(nominal_ref(3), "ok"),
                json!({"do": "user_confirm"}),
                recv(nominal_ref(6), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ),
        case(
            "p13-second-confirm",
            d,
            "A second joiner_confirm.",
            "inviter",
            none.clone(),
            vec![
                recv_p(nominal_ref(1), nominal_ref(2)),
                recv(nominal_ref(3), "ok"),
                json!({"do": "user_confirm"}),
                recv(nominal_ref(4), "ok"),
                recv(nominal_ref(4), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ),
        case(
            "p13-second-hello",
            d,
            "A second joiner_hello.",
            "inviter",
            none.clone(),
            vec![
                recv_p(nominal_ref(1), nominal_ref(2)),
                recv(nominal_ref(3), "ok"),
                recv(nominal_ref(3), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ),
        case(
            "p13-second-share",
            d,
            "A second share.",
            "inviter",
            none.clone(),
            vec![
                recv_p(nominal_ref(1), nominal_ref(2)),
                recv(nominal_ref(1), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ),
        case(
            "p13-second-reveal",
            d,
            "A second reveal while N is waiting for the provision.",
            "joiner",
            none.clone(),
            vec![
                recv_p(nominal_ref(0), nominal_ref(1)),
                recv_p(nominal_ref(2), nominal_ref(3)),
                json!({"do": "joiner_confirm", "history": true, "produces": nominal_ref(4)}),
                recv(nominal_ref(2), "pairing_failed"),
            ],
            Some("pairing_failed"),
        ),
    ];
    // A frame of A replayed to A, a frame of N replayed to N.
    for k in [0usize, 2, 5] {
        cases.push(case(
            &format!("p13-{}-replayed-to-inviter", r::FRAME_NAMES[k]),
            d,
            "A frame written by A is replayed to A.",
            "inviter",
            none.clone(),
            vec![recv(nominal_ref(k), "pairing_failed")],
            Some("pairing_failed"),
        ));
    }
    for k in [1usize, 3, 4, 6] {
        cases.push(case(
            &format!("p13-{}-replayed-to-joiner", r::FRAME_NAMES[k]),
            d,
            "A frame written by N is replayed to N.",
            "joiner",
            none.clone(),
            vec![recv(nominal_ref(k), "pairing_failed")],
            Some("pairing_failed"),
        ));
    }
    // After the last expected frame, frames are ignored.
    cases.push(case(
        "p13-ignored-after-ack",
        d,
        "After joiner_ack, A ignores the following frames.",
        "inviter",
        none.clone(),
        vec![
            recv_p(nominal_ref(1), nominal_ref(2)),
            recv(nominal_ref(3), "ok"),
            json!({"do": "user_confirm"}),
            recv(nominal_ref(4), "ok"),
            json!({"do": "provision", "produces": nominal_ref(5)}),
            recv(nominal_ref(6), "ok"),
            recv(nominal_ref(6), "ignored"),
            recv(nominal_ref(0), "ignored"),
        ],
        None,
    ));
    cases.push(case(
        "p13-ignored-after-provision",
        d,
        "After provision, N ignores the following frames.",
        "joiner",
        none,
        vec![
            recv_p(nominal_ref(0), nominal_ref(1)),
            recv_p(nominal_ref(2), nominal_ref(3)),
            json!({"do": "joiner_confirm", "history": true, "produces": nominal_ref(4)}),
            recv_p(nominal_ref(5), nominal_ref(6)),
            recv(nominal_ref(5), "ignored"),
            recv(nominal_ref(2), "ignored"),
        ],
        None,
    ));
    cases
}

fn p14_cases() -> Vec<Value> {
    let mut cases = Vec::new();
    for k in 0..7 {
        let name = r::FRAME_NAMES[k];
        let mut steps = prefix_steps(k);
        if k <= 1 {
            // Clear frames of another session look genuine; the key agreement fails further on.
            let next = if k == 0 { 2 } else { 3 };
            steps.push(recv(other_ref(k), "ok"));
            steps.push(recv(nominal_ref(next), "pairing_failed"));
        } else {
            steps.push(recv(other_ref(k), "pairing_failed"));
        }
        cases.push(case(
            &format!("p14-replay-{name}"),
            "P14",
            &format!("Frame {k} ({name}) of another session (other sid, other scalars, same code) is replayed in its place."),
            receiver_of(k),
            json!({}),
            steps,
            Some("pairing_failed"),
        ));
    }
    cases
}

/// A sealed frame of the nominal session with another body.
fn sealed_with(s: &r::Session, i: &r::Inputs, k: usize, body: &[u8]) -> Vec<u8> {
    if k == 2 {
        r::reveal_frame(&s.keys, &i.sid, &s.ya_pub, body)
    } else {
        r::sealed_frame(&s.keys, r::FRAME_TYPES[k], &i.sid, body)
    }
}

fn p15_cases(i: &r::Inputs, s: &r::Session) -> Vec<Value> {
    let ed = i.joiner.ed_pk;
    let x = i.joiner.x_pk;
    let ok_parts: Vec<(u8, &[u8])> = vec![(1, &ed), (2, &x), (3, b"Pixel"), (4, b"android")];
    let mut cases = Vec::new();
    let mut hello_case = |id: &str, desc: &str, body: Vec<u8>, expect: &str| {
        let frame = sealed_with(s, i, 3, &body);
        let mut steps = vec![
            recv_p(nominal_ref(1), nominal_ref(2)),
            recv(hex_ref(&frame), expect),
        ];
        let final_error = if expect == "ok" {
            None
        } else {
            Some(expect.to_owned())
        };
        if expect == "ok" {
            steps.push(json!({"do": "user_confirm"}));
        }
        let mut c = case(id, "P15", desc, "inviter", json!({}), steps, None);
        c["final_error"] = json!(final_error);
        c["body"] = json!(h(&body));
        cases.push(c);
    };
    let with = |extra: &[(u8, &[u8])]| {
        let mut p = ok_parts.clone();
        p.extend_from_slice(extra);
        r::tlv(&p)
    };
    hello_case(
        "p15-hello-unknown-tag-0x40",
        "An unknown tag 0x40 (additive extension) is ignored.",
        with(&[(0x40, b"future")]),
        "ok",
    );
    hello_case(
        "p15-hello-unknown-tag-0x7f",
        "The largest non-critical tag, 0x7f, is ignored.",
        with(&[(0x7f, b"")]),
        "ok",
    );
    hello_case(
        "p15-hello-critical-tag-0x90",
        "An unknown tag 0x90 is critical: pairing_unsupported.",
        with(&[(0x90, b"x")]),
        "pairing_unsupported",
    );
    hello_case(
        "p15-hello-critical-tag-0x80",
        "The first critical tag, 0x80.",
        with(&[(0x80, b"")]),
        "pairing_unsupported",
    );
    hello_case(
        "p15-hello-duplicate-tag",
        "A duplicate tag.",
        r::tlv(&[(1, &ed), (1, &ed), (2, &x), (3, b"Pixel"), (4, b"android")]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-disorder",
        "Tags that do not increase.",
        r::tlv(&[(2, &x), (1, &ed), (3, b"Pixel"), (4, b"android")]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-missing-name",
        "The mandatory name field is missing.",
        r::tlv(&[(1, &ed), (2, &x), (4, b"android")]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-ed-pk-31-bytes",
        "ed_pk de 31 octets.",
        r::tlv(&[(1, &ed[..31]), (2, &x), (3, b"Pixel"), (4, b"android")]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-name-empty",
        "name vide.",
        r::tlv(&[(1, &ed), (2, &x), (3, b""), (4, b"android")]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-name-65-chars",
        "name of 65 characters.",
        r::tlv(&[
            (1, &ed),
            (2, &x),
            (3, "x".repeat(65).as_bytes()),
            (4, b"android"),
        ]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-name-control-char",
        "name with a control character (BEL).",
        r::tlv(&[(1, &ed), (2, &x), (3, b"Pi\x07xel"), (4, b"android")]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-name-trailing-blank",
        "name with a trailing space.",
        r::tlv(&[(1, &ed), (2, &x), (3, b"Pixel "), (4, b"android")]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-platform-uppercase",
        "platform en majuscules.",
        r::tlv(&[(1, &ed), (2, &x), (3, b"Pixel"), (4, b"Android")]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-platform-empty",
        "platform vide.",
        r::tlv(&[(1, &ed), (2, &x), (3, b"Pixel"), (4, b"")]),
        "pairing_failed",
    );
    hello_case(
        "p15-hello-truncated-tlv",
        "A truncated TLV: the announced length exceeds the body.",
        vec![1, 0, 32, 0xaa],
        "pairing_failed",
    );

    // InviterHello: unknown tags, to N after the commit.
    let (aed, ax) = (i.inviter.ed_pk, i.inviter.x_pk);
    let inviter_parts: Vec<(u8, &[u8])> =
        vec![(1, &aed), (2, &ax), (3, b"PC-Bureau"), (4, b"windows")];
    let mut reveal_case = |id: &str, desc: &str, parts: Vec<(u8, &[u8])>, expect: &str| {
        let frame = sealed_with(s, i, 2, &r::tlv(&parts));
        let mut c = case(
            id,
            "P15",
            desc,
            "joiner",
            json!({}),
            vec![
                recv_p(nominal_ref(0), nominal_ref(1)),
                recv(hex_ref(&frame), expect),
            ],
            if expect == "ok" { None } else { Some(expect) },
        );
        c["body"] = json!(h(&r::tlv(&parts)));
        cases.push(c);
    };
    let mut p = inviter_parts.clone();
    p.push((0x40, b"future"));
    reveal_case(
        "p15-inviter-hello-unknown-tag-0x40",
        "InviterHello with an unknown tag 0x40: ignored.",
        p,
        "ok",
    );
    let mut p = inviter_parts.clone();
    p.push((0x90, b"x"));
    reveal_case(
        "p15-inviter-hello-critical-tag-0x90",
        "InviterHello with an unknown critical tag: pairing_unsupported.",
        p,
        "pairing_unsupported",
    );
    let mut p = inviter_parts.clone();
    p.push((5, &[0, 1, 2]));
    reveal_case(
        "p15-inviter-hello-member-count-3-bytes",
        "member_count of 3 bytes instead of 2.",
        p,
        "pairing_failed",
    );
    let mut p = inviter_parts.clone();
    p.push((6, &[0u8; 15]));
    reveal_case(
        "p15-inviter-hello-history-offer-15-bytes",
        "history_offer of 15 bytes instead of 16.",
        p,
        "pairing_failed",
    );

    // JoinerConfirm, to A after the hello and its own confirmation.
    let mut confirm_case = |id: &str, desc: &str, body: Vec<u8>, expect: &str| {
        let frame = sealed_with(s, i, 4, &body);
        let steps = vec![
            recv_p(nominal_ref(1), nominal_ref(2)),
            recv(nominal_ref(3), "ok"),
            json!({"do": "user_confirm"}),
            recv(hex_ref(&frame), expect),
        ];
        let mut c = case(
            id,
            "P15",
            desc,
            "inviter",
            json!({}),
            steps,
            if expect == "ok" { None } else { Some(expect) },
        );
        c["body"] = json!(h(&body));
        cases.push(c);
    };
    confirm_case(
        "p15-confirm-history-0x02",
        "history = 0x02: only the values 0x00 and 0x01 exist.",
        r::tlv(&[(1, &[2])]),
        "pairing_failed",
    );
    confirm_case(
        "p15-confirm-history-two-bytes",
        "history de deux octets.",
        r::tlv(&[(1, &[0, 0])]),
        "pairing_failed",
    );
    confirm_case(
        "p15-confirm-empty",
        "Empty body: the mandatory field is missing.",
        Vec::new(),
        "pairing_failed",
    );
    confirm_case(
        "p15-confirm-unknown-tag-0x40",
        "Unknown tag 0x40 ignored, history = 0.",
        r::tlv(&[(1, &[0]), (0x40, b"x")]),
        "ok",
    );
    confirm_case(
        "p15-confirm-critical-tag",
        "Tag critique 0xff.",
        r::tlv(&[(1, &[0]), (0xff, b"x")]),
        "pairing_unsupported",
    );

    // joiner_ack carries nothing.
    let frame = sealed_with(s, i, 6, b"x");
    cases.push(case(
        "p15-ack-not-empty",
        "P15",
        "joiner_ack with a non-empty body.",
        "inviter",
        json!({}),
        vec![
            recv_p(nominal_ref(1), nominal_ref(2)),
            recv(nominal_ref(3), "ok"),
            json!({"do": "user_confirm"}),
            recv(nominal_ref(4), "ok"),
            json!({"do": "provision", "produces": nominal_ref(5)}),
            recv(hex_ref(&frame), "pairing_failed"),
        ],
        Some("pairing_failed"),
    ));
    cases
}

fn p16_cases(i: &r::Inputs, s: &r::Session) -> Vec<Value> {
    let a = &i.inviter;
    let b = &i.joiner;
    let c = &i.other;
    let space = i.space_id.as_str();
    let other_space = "11111111-1111-4111-8111-111111111111";
    let stranger_x = r::Device::new("X", 0x01, 0x02).x_pk;
    let space_bytes = r::uuid16(space);
    let everyone = [(a.ed_pk, a.x_pk), (c.ed_pk, c.x_pk), (b.ed_pk, b.x_pk)];

    let body_with = |cert: Option<Vec<u8>>,
                     list: Option<Vec<u8>>,
                     sealed: Option<Vec<u8>>,
                     epoch: u32,
                     space_id: [u8; 16]| {
        r::provision_body(
            &space_id,
            epoch,
            &sealed.unwrap_or_else(|| s.sealed.clone()),
            &cert.unwrap_or_else(|| s.cert.clone()),
            &list.unwrap_or_else(|| s.member_list.clone()),
            s.history,
        )
    };
    let mut bad_sig_cert = s.cert.clone();
    let last = bad_sig_cert.len() - 1;
    bad_sig_cert[last] ^= 1;
    let mut bad_sig_list = s.member_list.clone();
    let last = bad_sig_list.len() - 1;
    bad_sig_list[last] ^= 1;
    let mut altered_sealed = s.sealed.clone();
    altered_sealed[60] ^= 1;
    let key2 = r::arr::<32>(&r::seq(0, 32));
    let sealed_for = |recipient: &r::Device, space_id: &str, epoch: u32| {
        r::sealed_space_key(
            space_id,
            epoch,
            &key2,
            &i.seal_ephemeral,
            &i.seal_nonce,
            &recipient.ed_pk,
            &recipient.x_pk,
        )
    };

    // (id, description, core error behind pairing_failed, provision body)
    let refused: Vec<(&str, &str, &str, Vec<u8>)> = vec![
        (
            "cert-subject-is-not-n",
            "The certificate subject is not N.",
            "pairing_failed",
            body_with(
                Some(r::device_cert(a, space, &c.ed_pk, &c.x_pk, i.now_ms)),
                None,
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "cert-issuer-is-not-a",
            "The certificate is signed by C and not by A.",
            "pairing_failed",
            body_with(
                Some(r::device_cert(c, space, &b.ed_pk, &b.x_pk, i.now_ms)),
                None,
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "cert-self-signed",
            "Certificate self-signed by N.",
            "pairing_failed",
            body_with(
                Some(r::device_cert(b, space, &b.ed_pk, &b.x_pk, i.now_ms)),
                None,
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "cert-other-space",
            "Certificate of another space.",
            "pairing_failed",
            body_with(
                Some(r::device_cert(a, other_space, &b.ed_pk, &b.x_pk, i.now_ms)),
                None,
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "cert-bad-signature",
            "Certificate signature altered.",
            "invalid_signature",
            body_with(Some(bad_sig_cert), None, None, i.key_epoch, space_bytes),
        ),
        (
            "list-signed-by-another",
            "List signed by C.",
            "pairing_failed",
            body_with(
                None,
                Some(r::member_list(c, space, i.key_epoch, i.now_ms, &everyone)),
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "list-other-epoch",
            "List of another epoch.",
            "pairing_failed",
            body_with(
                None,
                Some(r::member_list(a, space, 2, i.now_ms, &everyone)),
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "list-without-a",
            "List without A.",
            "pairing_failed",
            body_with(
                None,
                Some(r::member_list(
                    a,
                    space,
                    i.key_epoch,
                    i.now_ms,
                    &[(c.ed_pk, c.x_pk), (b.ed_pk, b.x_pk)],
                )),
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "list-a-with-another-x25519",
            "A appears in the list with a different X25519 key than in InviterHello.",
            "key_conflict",
            body_with(
                None,
                Some(r::member_list(
                    a,
                    space,
                    i.key_epoch,
                    i.now_ms,
                    &[(a.ed_pk, stranger_x), (c.ed_pk, c.x_pk), (b.ed_pk, b.x_pk)],
                )),
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "list-n-with-another-x25519",
            "N appears in the list with an X25519 key other than its own.",
            "key_conflict",
            body_with(
                None,
                Some(r::member_list(
                    a,
                    space,
                    i.key_epoch,
                    i.now_ms,
                    &[(a.ed_pk, a.x_pk), (c.ed_pk, c.x_pk), (b.ed_pk, stranger_x)],
                )),
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "list-other-space",
            "List of another space.",
            "pairing_failed",
            body_with(
                None,
                Some(r::member_list(
                    a,
                    other_space,
                    i.key_epoch,
                    i.now_ms,
                    &everyone,
                )),
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "list-bad-signature",
            "List signature altered.",
            "invalid_signature",
            body_with(None, Some(bad_sig_list), None, i.key_epoch, space_bytes),
        ),
        (
            "list-reserved-epoch",
            "List with a reserved epoch (2^31 + 1).",
            "malformed_statement",
            body_with(
                None,
                Some(r::member_list(a, space, 0x8000_0001, i.now_ms, &everyone)),
                None,
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "sealed-for-another-device",
            "Space key sealed for C.",
            "decryption_failed",
            body_with(
                None,
                None,
                Some(sealed_for(c, space, 1)),
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "sealed-for-another-space",
            "Space key sealed for another space.",
            "decryption_failed",
            body_with(
                None,
                None,
                Some(sealed_for(b, other_space, 1)),
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "sealed-for-another-epoch",
            "Space key sealed for epoch 2 while the batch says 1.",
            "decryption_failed",
            body_with(
                None,
                None,
                Some(sealed_for(b, space, 2)),
                i.key_epoch,
                space_bytes,
            ),
        ),
        (
            "sealed-altered",
            "Sealed space key altered.",
            "decryption_failed",
            body_with(None, None, Some(altered_sealed), i.key_epoch, space_bytes),
        ),
        (
            "epoch-reserved",
            "Reserved key_epoch (2^31 + 1) in the batch.",
            "pairing_failed",
            body_with(None, None, None, 0x8000_0001, space_bytes),
        ),
        (
            "epoch-zero",
            "Zero key_epoch in the batch.",
            "pairing_failed",
            body_with(None, None, None, 0, space_bytes),
        ),
        (
            "space-id-inconsistent",
            "Batch space_id differs from that of the certificate and the list.",
            "pairing_failed",
            body_with(None, None, None, i.key_epoch, r::uuid16(other_space)),
        ),
    ];
    let mut cases = Vec::new();
    for (id, desc, core_error, body) in refused {
        let frame = r::sealed_frame(&s.keys, 0x06, &i.sid, &body);
        let mut c = case(
            &format!("p16-{id}"),
            "P16",
            desc,
            "joiner",
            json!({}),
            vec![
                recv_p(nominal_ref(0), nominal_ref(1)),
                recv_p(nominal_ref(2), nominal_ref(3)),
                json!({"do": "joiner_confirm", "history": true, "produces": nominal_ref(4)}),
                recv(hex_ref(&frame), "pairing_failed"),
            ],
            Some("pairing_failed"),
        );
        // What the verification of the batch reports before the machine reduces it to pairing_failed.
        c["core_error"] = json!(core_error);
        c["body"] = json!(h(&body));
        cases.push(c);
    }
    // Control: the nominal batch is accepted.
    cases.push(case(
        "p16-control-nominal-batch",
        "P16",
        "Control: the nominal batch is accepted.",
        "joiner",
        json!({}),
        vec![
            recv_p(nominal_ref(0), nominal_ref(1)),
            recv_p(nominal_ref(2), nominal_ref(3)),
            json!({"do": "joiner_confirm", "history": true, "produces": nominal_ref(4)}),
            recv_p(nominal_ref(5), nominal_ref(6)),
        ],
        None,
    ));
    cases
}
